def transform(grid):
    pts=sorted((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5)
    def cross(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    lo=[];hi=[]
    for p in pts:
        while len(lo)>1 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    for p in reversed(pts):
        while len(hi)>1 and cross(hi[-2],hi[-1],p)<=0: hi.pop()
        hi.append(p)
    hull=lo[:-1]+hi[:-1]
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==5 or (v and len(hull)>=3 and all(cross(hull[i],hull[(i+1)%len(hull)],(r,c))>0 for i in range(len(hull)))): out[r][c]=0
    return out

